CREATE TABLE IF NOT EXISTS customers(id BIGINT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255) UNIQUE NOT NULL,name VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS products(id BIGINT AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(80) UNIQUE NOT NULL,name VARCHAR(200) NOT NULL,stock INT NOT NULL,price DECIMAL(10,2) NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(80) UNIQUE NOT NULL,customer_id BIGINT NOT NULL,status VARCHAR(40) NOT NULL,tracking_number VARCHAR(100));
CREATE TABLE IF NOT EXISTS order_items(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,product_id BIGINT NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL);
CREATE TABLE IF NOT EXISTS inquiries(id BIGINT AUTO_INCREMENT PRIMARY KEY,idempotency_key VARCHAR(128) UNIQUE NOT NULL,customer_email VARCHAR(255),subject VARCHAR(500),body TEXT,category VARCHAR(40),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS refund_requests(id BIGINT AUTO_INCREMENT PRIMARY KEY,idempotency_key VARCHAR(128) UNIQUE NOT NULL,order_number VARCHAR(80),reason TEXT,status VARCHAR(40) DEFAULT 'PENDING_MANUAL_APPROVAL',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
